import os, pandas as pd; p=os.path.join(os.environ['WORKSPACE_DATA'], 'daily_bars', 'part-000.parquet'); df = pd.read_parquet(p); df = df[df['session_date'] <= '2025-01-09']; 
# Pivot to get close prices
wide = df.pivot(index='session_date', columns='asset_id', values='close'); 
# Compute last 20-day returns (or as many days as available)
ret20 = wide.pct_change(20).dropna(how='all'); 
# Normalize returns across assets
corr = ret20.corr(); 
# Rank assets by Sharpe Ratio (annualized) and volatility
sharpe = ret20.mean() / ret20.std() * (252**0.5); 
vol = ret20.std(); 
ranked = pd.DataFrame({'sharpe': sharpe, 'vol': vol, 'return': ret20.loc['2025-01-09', :]}, index=wide.columns).sort_values(by=['sharpe', 'vol'], ascending=[False, True]).head(10); 
print('Top 10 assets by Sharpe and volatility:')
print(ranked.to_string())
